package com.johannesmager.pictorres.storage;

import java.util.Objects;
import java.util.regex.Pattern;

/**
 * Relative location of a stored file, e.g. {@code originals/2026/10/<uuid>.jpg}.
 *
 * <p>Keys are only ever generated by the server. The strict format check makes it impossible to
 * address anything outside the storage root, even if a key is read back from an untrusted source.
 */
public record StorageKey(String value) {

  private static final String UUID = "[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}";
  private static final String EXT = "[a-z0-9]{1,5}";
  private static final Pattern FORMAT =
      Pattern.compile(
          "(originals/\\d{4}/\\d{2}/"
              + UUID
              + "\\."
              + EXT
              + ")|(thumbnails/"
              + UUID
              + "\\."
              + EXT
              + ")");

  public StorageKey {
    Objects.requireNonNull(value, "value");
    if (!FORMAT.matcher(value).matches()) {
      throw new IllegalArgumentException("Invalid storage key: " + value);
    }
  }

  @Override
  public String toString() {
    return value;
  }
}
